{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Launch template EBS volume encryption is not enforced",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "MEDIUM",
      "explanation": "The launch template does not explicitly encrypt its root EBS volume, so instances may store data on unencrypted volumes when EBS encryption by default is not enabled for the account."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "IMDSv2 tokens are not required",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "HIGH",
      "explanation": "The launch template does not require session tokens for instance metadata access, allowing use of IMDSv1 and increasing the risk of credential theft through SSRF-style attacks."
    }
  ],
  "patched_code": "resource "aws_launch_template" "changeme_simple_asg_launch_template_nlb" {
  name                   = "changeme-simple-asg-launch-template-nlb"
  image_id               = data.aws_ami.changeme_amazon_nlb_ami.id
  instance_type          = "t2.micro"
  vpc_security_group_ids = [aws_security_group.changeme_nlb_aws_security_group.id]
  user_data              = filebase64("${path.module}/user_data.sh")

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      encrypted = true
    }
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }
}
",
  "fix_summary": "Added encrypted EBS root volume configuration and required IMDSv2 tokens for instances launched from the template."
}
